{"code": "import nanosurf, time, os, glob
spm = nanosurf.SPM()
app = spm.application
scan = app.Scan
# set parameters
scan.ImageWidth = 10e-6
scan.ImageHeight = 10e-6
scan.Points = 128
scan.Lines = 128
scan.Scantime = 0.4
# set tapping mode if possible
if hasattr(app, 'OperatingMode'):
    try:
        if hasattr(app.OperatingMode, 'Mode'):
            app.OperatingMode.Mode = 'Tapping'
        elif hasattr(app.OperatingMode, 'set_mode'):
            app.OperatingMode.set_mode('Tapping')
    except Exception:
        pass
# start scan (upwards)
if hasattr(scan, 'StartFrameUp'):
    scan.StartFrameUp()
else:
    raise RuntimeError('StartFrameUp not available')
# wait until scanning finished
while getattr(scan, 'IsScanning', False):
    # optional: print progress
    time.sleep(2)
# after scan, list image files in current working directory
cwd = getattr(scan, 'CurrentWorkingDirectory', None)
if not cwd:
    cwd = os.getcwd()
image_files = []
for ext in ('*.tif', '*.tiff', '*.png', '*.jpg', '*.jpeg'):
    image_files.extend(glob.glob(os.path.join(cwd, '**', ext), recursive=True))
if not image_files:
    # fallback: list any files in cwd
    image_files = [os.path.join(cwd, f) for f in os.listdir(cwd) if os.path.isfile(os.path.join(cwd, f))]
print('Found files:', image_files)
if image_files:
    print('Latest:', max(image_files, key=os.path.getmtime))
